Tomeka: What you’ve neglected to consider is that unlike Nobel laureates, sports celebrities earn millions of dollars for their employers in the form of gate receipts and TV rights.$batch06$ AND q.prompt=$batch06$Franklin's and Tomeka's statements provide the most support for holding that they disagree about the truth of which one of the following?$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT107-S4-Q16'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT107-S4-Q16$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S4-Q16'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT107-S4-Q16$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Franklin's Position$batch06$, $batch06$Paying sports stars ten times what Nobel laureates earn is inconsistent, since both have rare talent and work hard.$batch06$), (1, $batch06$Tomeka's Position$batch06$, $batch06$Unlike laureates, sports stars earn millions for their employers.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$"Inconsistent" means there is no good reason for the gap. Tomeka gives exactly that: a reason. Revenue for employers explains the pay difference. So they disagree about whether the gap has a rational basis.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether there is a rational basis for the salary difference.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT107-S4-Q16$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Neither speaker talks about taking laureates seriously.$batch06$), ($batch06$B$batch06$, $batch06$This is the most popular wrong answer. Franklin finds the gap inconsistent, but he never says laureates should earn *more* than athletes. Equal pay would fix the inconsistency too.$batch06$), ($batch06$C$batch06$, $batch06$Franklin says both work hard. Tomeka does not dispute it.$batch06$), ($batch06$D$batch06$, $batch06$Franklin says the gap is inconsistent, meaning no rational basis. Tomeka supplies one: revenue.$batch06$), ($batch06$E$batch06$, $batch06$Neither speaker argues about what social contributions should be.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT107-S4-Q16$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
